func active(p page, keys ...string) bool {
	for _, k := range keys {
		if p.Key == k {
			return true
		}
	}
	return false
}

func anchor(name string) templ.Attributes {
	return templ.Attributes{"data-tour": "referenz.leiste." + name}
}

